@Override protected JsonArray serve(String filter,int limit){
  JsonArray array=new JsonArray();
  if (PersistS3.S3 == null)   return array;
  filter=Strings.nullToEmpty(filter);
  try {
    for (Bucket b : PersistS3.S3.listBuckets()) {
      if (b.getName().startsWith(filter)) array.add(new JsonPrimitive(b.getName()));
      if (array.size() == limit) break;
    }
  } catch (RuntimeException e) {
    e.printStackTrace();
    return array;
  }
  return array;
}
